const items = $input.all();
let rawData = "";
if (items[0] && items[0].json) {
  rawData = items[0].json.data || items[0].json.body || "";
  if (!rawData && typeof items[0].json === "string") rawData = items[0].json;
  if (!rawData) {
    const vals = Object.values(items[0].json);
    if (vals.length > 0 && typeof vals[0] === "string") rawData = vals[0];
  }
}

const cleanHtml = (str) => (str || "")
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
  .replace(/<[^>]+>/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&apos;|&#39;|&#x27;/g, "'")
  .replace(/&quot;|&#34;/g, '"')
  .replace(/&lt;/g, "<")
  .replace(/&gt;/g, ">")
  .replace(/\s+/g, " ")
  .trim();

// 优先生成 1200x630 / 1200x600 高清大卡，彻底告别 300x168 糊图
function getImageUrl(link, blockPic) {
  if (!link || typeof link !== "string") {
    return (blockPic && blockPic.startsWith("http")) ? blockPic : "";
  }
  const ghMatch = link.match(/^https?:\/\/github\.com\/([^\/]+)\/([^\/\?#]+)/);
  if (ghMatch) {
    return `https://opengraph.githubassets.com/1/${ghMatch[1]}/${ghMatch[2]}`;
  }
  if (link.startsWith("http") && !link.includes("news.ycombinator.com") && !link.includes("trends.google.com")) {
    return `https://v1.screenshot.11ty.dev/${encodeURIComponent(link)}/opengraph/`;
  }
  if (blockPic && blockPic.startsWith("http")) return blockPic;
  return "";
}

const staticData = $getWorkflowStaticData("global");
staticData.seenLinks = Array.isArray(staticData.seenLinks) ? staticData.seenLinks : [];

let targetCategory = "硬核技术";
let categoryKey = "tech";
let feedUrl = "";

try {
  const p = $("prep-feed").first().json;
  if (p.targetCategory) targetCategory = p.targetCategory;
  if (p.categoryKey) categoryKey = p.categoryKey;
  if (p.feedUrl) feedUrl = p.feedUrl;
} catch (e) {}

const isTrends = (categoryKey === "trends") || (feedUrl.includes("trends.google.com")) || (targetCategory.includes("趋势"));
const candidates = [];

if (isTrends) {
  const itemRegex = /<item>([\s\S]*?)<\/item>/g;
  let match;
  while ((match = itemRegex.exec(rawData)) !== null) {
    const block = match[1];
    const titleM = block.match(/<title>([\s\S]*?)<\/title>/);
    const newsM = block.match(/<ht:news_item_title>([\s\S]*?)<\/ht:news_item_title>/);
    const urlM = block.match(/<ht:news_item_url>([\s\S]*?)<\/ht:news_item_url>/);
    const trafficM = block.match(/<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/);
    const picM = block.match(/<ht:picture>([\s\S]*?)<\/ht:picture>/) || block.match(/<ht:news_item_picture>([\s\S]*?)<\/ht:news_item_picture>/);

    const title = titleM ? cleanHtml(titleM[1]) : "";
    const newsTitle = newsM ? cleanHtml(newsM[1]) : "";
    const newsUrl = urlM ? cleanHtml(urlM[1]) : "";
    const traffic = trafficM ? cleanHtml(trafficM[1]) : "";
    const picUrl = picM ? cleanHtml(picM[1]) : "";
    const imageUrl = getImageUrl(newsUrl, picUrl);

    if (title && newsTitle) {
      candidates.push({
        title: title,
        news_event: newsTitle,
        traffic: traffic,
        link: newsUrl || "https://trends.google.com/trending",
        image_url: imageUrl
      });
    }
  }
} else {
  // 优先解析 Algolia HN JSON 接口（带真实项目正文 story_text 和热度数据）
  let parsedJson = null;
  try {
    parsedJson = typeof rawData === "object" ? rawData : JSON.parse(rawData);
  } catch (e) {}

  if (parsedJson && Array.isArray(parsedJson.hits)) {
    for (const hit of parsedJson.hits) {
      const title = cleanHtml(hit.title);
      const link = hit.url || `https://news.ycombinator.com/item?id=${hit.objectID}`;
      const storyText = cleanHtml(hit.story_text).slice(0, 350);
      const meta = `热度: ${hit.points || 0}赞 / ${hit.num_comments || 0}评论`;
      const snippet = storyText ? `${meta} | 核心介绍: ${storyText}` : meta;
      const imageUrl = getImageUrl(link);

      if (title) {
        candidates.push({
          title: title,
          link: link,
          snippet: snippet,
          image_url: imageUrl
        });
      }
    }
  } else {
    // 兼容传统 XML RSS 兜底
    const itemRegex = /<item>([\s\S]*?)<\/item>/g;
    let match;
    while ((match = itemRegex.exec(rawData)) !== null) {
      const block = match[1];
      const titleM = block.match(/<title>([\s\S]*?)<\/title>/);
      const linkM = block.match(/<link>([\s\S]*?)<\/link>/);
      const descM = block.match(/<description>([\s\S]*?)<\/description>/);
      const picM = block.match(/<media:content[^>]*url=["']([^"']+)["']/i) || block.match(/<enclosure[^>]*url=["']([^"']+)["']/i);

      const title = titleM ? cleanHtml(titleM[1]) : "";
      const link = linkM ? cleanHtml(linkM[1]) : "";
      const snippet = descM ? cleanHtml(descM[1]) : title;
      const picUrl = picM ? cleanHtml(picM[1]) : "";
      const imageUrl = getImageUrl(link, picUrl);

      if (title && link) {
        candidates.push({
          title: title,
          link: link,
          snippet: snippet,
          image_url: imageUrl
        });
      }
    }
  }
}

// 去重过滤
let unseen = candidates.filter(item => {
  return !staticData.seenLinks.includes(item.link) && !staticData.seenLinks.includes(item.title);
});

if (unseen.length === 0 && candidates.length > 0) {
  const currentIds = new Set();
  candidates.forEach(c => { currentIds.add(c.link); currentIds.add(c.title); });
  staticData.seenLinks = staticData.seenLinks.filter(id => !currentIds.has(id));
  unseen = candidates;
}

const finalCandidates = unseen.slice(0, 15);

return [{
  json: {
    targetCategory: isTrends ? "谷歌趋势" : targetCategory,
    categoryKey: isTrends ? "trends" : categoryKey,
    candidates: finalCandidates
  }
}];

