const item = $input.item.json;
const cb = item.callback_query;
if (!cb) return [];

const chatId = cb.message ? cb.message.chat.id : 0;
// 安全锁：非本人操作直接拦截
if (String(chatId) !== "YOUR_TELEGRAM_CHAT_ID") return [];

const data = cb.data || "";
const msgText = cb.message ? (cb.message.text || "") : "";
const messageId = cb.message ? cb.message.message_id : null;
const queryId = cb.id;

if (data === "fetch_biz" || data === "fetch_tech" || data === "fetch_trends") {
  let feedType = "biz";
  let toast = "💼 正在搜寻独立商业项目...";
  if (data === "fetch_tech") {
    feedType = "tech";
    toast = "⚡ 正在搜寻硬核技术热点...";
  } else if (data === "fetch_trends") {
    feedType = "trends";
    toast = "🍉 正在搜寻海外吃瓜热点...";
  }

  return [{
    json: {
      action: "fetch",
      feedType: feedType,
      queryId: queryId,
      chatId: chatId,
      messageId: messageId,
      toast: toast
    }
  }];
}

if (data === "ignore") {
  return [{
    json: {
      action: "ignore",
      queryId: queryId,
      chatId: chatId,
      messageId: messageId,
      toast: "🗑️ 已跳过此推文草稿"
    }
  }];
}

let selectedText = "";
let mode = data.includes("queue") ? "addToQueue" : "shareNow";
let label = data.endsWith("_a") ? "候选 A" : "候选 B";

if (data.endsWith("_a")) {
  const matchA = msgText.match(/🅰️ 【候选 A[^】]*】\n+([\s\S]*?)(?=\n+🅱️)/);
  selectedText = matchA ? matchA[1].trim() : "";
} else if (data.endsWith("_b")) {
  const matchB = msgText.match(/🅱️ 【候选 B[^】]*】\n+([\s\S]*?)(?=\n+请在手机上)/);
  selectedText = matchB ? matchB[1].trim() : "";
}

// 提取配图：若用户点击的是纯文本发送（text_a 或 text_b），绝不带图！
let imageUrl = "";
const isPureText = data.startsWith("text_");

if (!isPureText) {
  const imgMatch = msgText.match(/🖼️ 配图：(https?:\/\/[^\s\n]+)/);
  imageUrl = imgMatch ? imgMatch[1].trim() : "";
}

let toast = "";
if (isPureText) {
  toast = "📝 正在以【纯文本】直发 X...";
} else if (mode === "shareNow") {
  toast = imageUrl ? "🚀 正在【带图】直发 X..." : "🚀 正在直发 X...";
} else {
  toast = imageUrl ? "⏱️ 正在【带图】加入排期..." : "⏱️ 正在加入排期队列...";
}

return [{
  json: {
    action: "publish",
    queryId: queryId,
    chatId: chatId,
    messageId: messageId,
    selectedLabel: label + (isPureText ? "（纯文本）" : (imageUrl ? "（带图）" : "")),
    selectedText: selectedText || msgText,
    imageUrl: imageUrl,
    mode: mode,
    toast: toast
  }
}];

