const item = $input.item.json;
const raw = item.text || "";
const cleaned = raw.replace(/^```json\s*/i, "").replace(/^```\s*/, "").replace(/\s*```$/, "").trim();

// 强力 JSON 解析器（兼容大模型未转义物理换行符的情况）
function safeParseJson(str) {
  try {
    return JSON.parse(str);
  } catch (e1) {
    try {
      // 修复字符串值内部的真实换行符
      const fixed = str.replace(/"((?:[^"\\]|\\.)*)"/g, (match) => {
        return match.replace(/\r?\n/g, "\\n");
      });
      return JSON.parse(fixed);
    } catch (e2) {
      const extract = (key) => {
        const m = str.match(new RegExp(`"${key}"\\s*:\\s*"([\\s\\S]*?)"(?=\\s*,\\s*"|\\s*})`));
        return m ? m[1].replace(/\\n/g, "\n") : "";
      };
      return {
        category: extract("category") || "谷歌趋势",
        selected_title: extract("selected_title") || "今日海外热搜",
        source_url: extract("source_url") || "",
        summary: extract("summary") || "解析兜底：请查看候选正文",
        candidate_a: extract("candidate_a") || str.slice(0, 120),
        candidate_b: extract("candidate_b") || str.slice(0, 120)
      };
    }
  }
}

const parsed = safeParseJson(cleaned);

let sourceUrl = parsed.source_url || "";
let imageUrl = "";

try {
  const candList = $("code-slice").first().json.candidates || [];
  let matched = candList.find(c => c.title === parsed.selected_title || c.news_event === parsed.selected_title);
  if (!matched && sourceUrl) {
    matched = candList.find(c => c.link === sourceUrl);
  }
  if (!matched && candList.length > 0) {
    matched = candList[0];
  }
  if (matched) {
    if (!sourceUrl || !sourceUrl.startsWith("http")) sourceUrl = matched.link;
    if (matched.image_url) imageUrl = matched.image_url;
  }
} catch (e) {}

function formatXPost(text) {
  if (!text) return "";
  let clean = text.replace(/\\n/g, "\n").replace(/。/g, "");
  if (clean.includes("\n")) {
    const lines = clean.split("\n").map(l => l.trim()).filter(Boolean);
    return lines.join("\n");
  }
  const parts = clean.split(/\s{2,}/).map(p => p.trim()).filter(Boolean);
  if (parts.length > 2) {
    return parts.join("\n");
  }
  return clean.trim();
}

const candidateA = formatXPost(parsed.candidate_a);
const candidateB = formatXPost(parsed.candidate_b);

const staticData = $getWorkflowStaticData("global");
staticData.seenLinks = Array.isArray(staticData.seenLinks) ? staticData.seenLinks : [];
if (sourceUrl) staticData.seenLinks.push(sourceUrl);
if (parsed.selected_title) staticData.seenLinks.push(parsed.selected_title);
if (staticData.seenLinks.length > 300) {
  staticData.seenLinks = staticData.seenLinks.slice(-150);
}

const category = parsed.category || "谷歌趋势";
let header = "⚡ 【今日破圈技术热点】";
let labelA = "极致短句流・实名避坑";
let labelB = "短长错落流・批判对线";

if (category.includes("商业") || category.includes("biz")) {
  header = "💼 【今日独立商业・抉择拆解】";
  labelA = "模式壁垒争议流";
  labelB = "运营抉择二选一";
} else if (category.includes("趋势") || category.includes("trends")) {
  header = "🍉 【今日海外热搜・第一手吃瓜速递】";
  labelA = "冲浪一线・大瓜速递";
  labelB = "毒舌看戏・人间清醒";
}

return [{
  json: {
    category: category,
    header: header,
    label_a: labelA,
    label_b: labelB,
    selected_title: parsed.selected_title || "",
    source_url: sourceUrl,
    image_url: imageUrl,
    summary: parsed.summary || "",
    candidate_a: candidateA,
    candidate_b: candidateB
  }
}];

const staticData = $getWorkflowStaticData("global");
staticData.seenLinks = Array.isArray(staticData.seenLinks) ? staticData.seenLinks : [];

let text = "";
let feedType = "";

try {
  const item = $input.item.json;
  // 安全锁：如果是 TG 触发的消息，校验是否为本人 ChatID
  const incomingChatId = item.message?.chat?.id || item.chatId;
  if (incomingChatId && String(incomingChatId) !== "YOUR_TELEGRAM_CHAT_ID") {
    return [];
  }
  if (item.message && item.message.text) {
    text = item.message.text.trim();
  }
  if (item.feedType) {
    feedType = item.feedType;
  }
} catch (e) {}

try {
  if (!feedType && $("parse-selection").isExecuted) {
    const ps = $("parse-selection").first().json;
    if (ps && ps.feedType) feedType = ps.feedType;
  }
} catch (e) {}

const feeds = {
  "biz": "https://hn.algolia.com/api/v1/search_by_date?tags=show_hn&hitsPerPage=25",
  "tech": "https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=25",
  "trends": "https://trends.google.com/trending/rss?geo=US"
};

if (text.startsWith("/biz") || feedType === "biz") {
  staticData.lastCategory = "独立商业";
  return [{
    json: {
      targetCategory: "独立商业",
      categoryKey: "biz",
      feedUrl: feeds.biz
    }
  }];
} else if (text.startsWith("/tech") || feedType === "tech") {
  staticData.lastCategory = "硬核技术";
  return [{
    json: {
      targetCategory: "硬核技术",
      categoryKey: "tech",
      feedUrl: feeds.tech
    }
  }];
} else if (text.startsWith("/trends") || feedType === "trends") {
  staticData.lastCategory = "谷歌趋势";
  return [{
    json: {
      targetCategory: "谷歌趋势",
      categoryKey: "trends",
      feedUrl: feeds.trends
    }
  }];
} else {
  const categories = ["独立商业", "硬核技术", "谷歌趋势"];
  const keys = ["biz", "tech", "trends"];
  const currentIndex = categories.indexOf(staticData.lastCategory);
  const nextIndex = (currentIndex + 1) % categories.length;
  const nextCategory = categories[nextIndex];
  const nextKey = keys[nextIndex];
  staticData.lastCategory = nextCategory;

  return [{
    json: {
      targetCategory: nextCategory,
      categoryKey: nextKey,
      feedUrl: feeds[nextKey]
    }
  }];
}
